draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('1546', W/2, H/2);
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 60);
  ctx.lineTo(W/2, H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 60, H/2);
  ctx.lineTo(W/2 + 60, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 40 * Math.sin(t), H/2 + 40 * Math.cos(t), 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 40 * Math.sin(t + Math.PI), H/2 + 40 * Math.cos(t + Math.PI), 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.restore();
}
